def e8arr(x): return np.ldexp(np.ones_like(x,dtype=np.float32), x.astype(np.int32)-127)
def unpack_fp4_weight(w,sc,indim):
 out=w.shape[0]; codes=np.empty((out,indim),np.uint8); codes[:,0::2]=w & 0xF; codes[:,1::2]=w >> 4
 vals=FP4_VAL[codes].astype(np.float32); scales=e8arr(sc)
