def fp4_linear(x_bf16,w_u8,sc_u8,indim):
 w=unpack_fp4_weight(np.asarray(w_u8,np.uint8),np.asarray(sc_u8,np.uint8),indim); return (bf16_to_f32(x_bf16) @ w.T).astype(np.float32)
